+
+/** Escape text for the data part of a workflow command. */
+export function annotation(error) {
+  const text = String(error?.message || error)
+    .replaceAll('%', '%25')
+    .replaceAll('\r', '%0D')
+    .replaceAll('\n', '%0A');
