+}
+
+export async function main(env = process.env) {
+  const request = githubApi({
+    token: env.GITHUB_TOKEN,
+    apiUrl: env.GITHUB_API_URL || undefined,
+  });
+  const base = `/repos/${env.GITHUB_REPOSITORY}/pages`;
+  let pending = null;
