+        blank = false;
+        return line.raw;
+      }
+      const value = line.text.replace(/[ \t]+$/, '');
+      if (!value && blank) {
+        return '';
+      }
+      blank = !value;
+      return value + (line.raw.endsWith('\n') ? '\n' : '');
