+  // Synchronize package-lock.json
+  console.log('\nSynchronizing package-lock.json...');
+
+  syncVersionLock(jsRoot, before);
+
+  console.log('\n✅ Instant version bump complete');
+  console.log(`Version: ${oldVersion} → ${newVersion}`);
