+    'docs/',
+    'examples/',
+    'experiments/',
+    'dev/log/',
+    '.changeset/',
+  ];
+  const requiresChangeset = packagePaths.some(
+    (path) =>
+      !path.endsWith('.md') && !ignored.some((dir) => path.startsWith(dir))
+  );
