+  // Get changeset files added in this PR
+  const addedChangesetFiles = getAddedChangesetFiles(changesetDir, jsRoot);
+  if (addedChangesetFiles === null) {
+    process.exit(0);
+  }
+  const changesetCount = addedChangesetFiles.length;
