+          let finalCloudCodeUrl = cloudCodeUrl;
+          if (isStreamingRequest(originalUrl)) {
+            const separator = finalCloudCodeUrl.includes('?') ? '&' : '?';
+            finalCloudCodeUrl = `${finalCloudCodeUrl}${separator}alt=sse`;
