+              log.info(() => ({
+                message: 'retrying cloud code api request',
+                attempt,
+                delayMs: delay,
+                previousStatus: lastResponse?.status,
+              }));
+              await new Promise((resolve) => setTimeout(resolve, delay));
+            }
