+            log.error(() => ({
+              message: 'cloud code api error and no api key fallback available',
+              status: cloudCodeResponse.status,
+              hint: 'Set GOOGLE_GENERATIVE_AI_API_KEY or GEMINI_API_KEY environment variable for fallback',
+            }));
