+          if (fallbackApiKey) {
+            log.warn(() => ({
+              message:
+                'oauth scope error, falling back to api key authentication',
+              hint: 'This should not happen with Cloud Code API routing',
+              url: originalUrl.substring(0, 100),
+            }));
