+            log.error(() => ({
+              message: 'oauth scope error and no api key fallback available',
+              hint: 'Set GOOGLE_GENERATIVE_AI_API_KEY or GEMINI_API_KEY environment variable',
+              url: originalUrl.substring(0, 100),
+            }));
