+export async function resolveModel(input: {
+  model: PromptInput['model'];
+  agent: Agent.Info;
+}) {
+  if (input.model) {
+    return input.model;
+  }
+  if (config.dryRun) {
+    return Provider.defaultModel();
+  }
+  if (input.agent.model) {
+    return input.agent.model;
+  }
+  return Provider.defaultModel();
+}
